local a=require("fcs.io.cfgspec")local b=require("fcs.io.fsx")local c={}function c.bind(d,e,f)if d.thrusters[e]~=nil then d.thrusters[e]=f elseif d.sensors[e]~=nil then d.sensors[e]=f elseif e=="fuelRelay"then d.fuelRelay=f end;return d end;function c.measureWrite(g,h,i)local j=os.epoch("utc")for k=1,i do g:setThruster(h,k%2==0)end;return(os.epoch("utc")-j)/i end;local l="/eh2_hw_config.tbl"local m=b.read;local n=b.writeAtomic;function c.loadBinding(read)local o,p,q=a.load("devbind",read)if q then return nil,q end;if not p then local r=read(l)if r~=nil then local s=textutils.unserialise(r)if type(s)=="table"then o=a.merge("devbind",a.splitLegacy(s).devbind)end end end;return o end;local function t(read)return a.load("senscal",read)end;local function u(v)for w,f in ipairs(v.getNames())do print(f.."  ["..tostring(v.getType(f)).."]")end end;function c.run()local v=require("fcs.io.shim")local x=require("fcs.io.backend")local d,y=c.loadBinding(m)if y then print("corrupt "..a.FILES.devbind..": "..tostring(y))return end;while true do print("\n== EH2 PROBE == 1 discover 2 bind 3 sensors 4 thruster 5 timing 6 roles 7 methods q quit")local z=read()if z=="1"then u(v)elseif z=="2"then write("role (e.g. FL / gimbal / fuelRelay): ")local e=read()write("peripheral name: ")local f=read()d=c.bind(d,e,f)a.save("devbind",d,n)print("bound "..e.." -> "..f)elseif z=="3"then local A={thrusters=d.thrusters,sensors=d.sensors,fuelRelay=d.fuelRelay,bindings=t(m)}local B=x.new(v,A)B:sensors()for w=1,10 do local C=B:sensors()print(("alt %.2f v %.2f pitch %.3f roll %.3f hdg %.3f yawR %.3f sway %.2f surge %.2f gnd %s"):format(C.altitude,C.vSpeed,C.pitch,C.roll,C.heading,C.yawRate,C.swayVel,C.surgeVel,tostring(C.onGround)))sleep(0.3)end elseif z=="4"then write("peripheral NAME (e.g. thruster_1): ")local f=read()local D=f~=""and v.wrap(f)or nil;if not D then print("no such peripheral: "..tostring(f))elseif not D.setPower then print(tostring(f).." has no setPower. Its methods:")local E=peripheral.getMethods(f)if E then local C=""for w,F in ipairs(E)do C=C..F.." "end;print(C)else print("(none)")end else D.setPower(15)sleep(0.5)print("thrustKN="..tostring(D.getCurrentThrustKN and D.getCurrentThrustKN()or"n/a"))D.setPower(0)end elseif z=="5"then write("peripheral NAME: ")local f=read()local D=f~=""and v.wrap(f)or nil;if not D or not D.setPower then print("no thruster peripheral: "..tostring(f))else local i=40;local j=os.epoch("utc")for k=1,i do D.setPower(k%2==0 and 15 or 0)end;D.setPower(0)print(("avg %.2f ms/write over %d writes"):format((os.epoch("utc")-j)/i,i))end elseif z=="6"then print("THRUSTERS: FL FR RL RR (lift) | YFL YFR YRL YRR (lateral) | MAIN (accel) | FRL FRR (front brakes)")print("SENSORS: altimeter gimbal navTable downOptical velFront velRear velMedial | fuelRelay")elseif z=="7"then write("peripheral NAME: ")local f=read()local E=peripheral.getMethods(f)if not E then print("no such peripheral: "..tostring(f))else local C=""for w,F in ipairs(E)do C=C..F.." "end;print(C)end elseif z=="q"then return end end end;return c